import{_ as o,c,o as d,b0 as t}from"./chunks/framework.BWMBvyU7.js";const A="data:image/jpeg;base64,",a="/programming-docs/assets/image-20220624065401119.BBZwzaSy.png",g=JSON.parse('{"title":"LV005-socket基础","description":null,"frontmatter":{"title":"LV005-socket基础","date":"2026-03-16T14:16:36.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/net/net-programming/126d38f258440f43fcb3026e","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-16T14:16:36.244Z","fulluuid":"3fcb3026eb99492e932c7bc03d85a009","useduuid":"3fcb3026e"}},"headers":[],"relativePath":"sdoc/net/net-programming/126d38f258440f43fcb3026e.md","filePath":"sdoc/04-网络相关/20-网络编程/LV005-socket基础.md","lastUpdated":1773672539000}'),s={name:"sdoc/net/net-programming/126d38f258440f43fcb3026e.md"};function r(i,e,n,l,p,k){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="lv005-socket基础" tabindex="-1">LV005-socket基础 <a class="header-anchor" href="#lv005-socket基础" aria-label="Permalink to &quot;LV005-socket基础&quot;">​</a></h1><p>本文主要是网络编程——socket基础知识的相关笔记，若笔记中有错误或者不合适的地方，欢迎批评指正😃。</p><h2 id="一、什么是socket" tabindex="-1">一、什么是<code>socket</code> <a class="header-anchor" href="#一、什么是socket" aria-label="Permalink to &quot;一、什么是`socket`&quot;">​</a></h2><h3 id="_1-scoket概述" tabindex="-1">1. <code>scoket</code>概述 <a class="header-anchor" href="#_1-scoket概述" aria-label="Permalink to &quot;1. `scoket`概述&quot;">​</a></h3><img src="'+A+'" alt="socket是什么？" style="zoom:67%;"><p><code>socket</code> 的原意是插座，插口，但是在计算机通信领域，<code>socket</code> 被翻译为<strong>套接字</strong>，它是计算机之间进行通信的一种约定或一种方式。它是一个编程接口，是一种特殊的文件描述符 (<code>everything in Unix is a file</code>)，它并不仅限于<code>TCP/IP</code>协议，我们可以使用它来进行面向连接 (如<code>Transmission Control Protocol - TCP/IP</code>)的编程，也可以使用它进行面向无连接 (如<code>User Datagram Protocol -UDP</code>和<code>Inter-network Packet Exchange - IPX</code>)的编程。</p><p>我们通过 <code>socket</code> 这种约定，一台计算机可以接收其他计算机的数据，也可以向其他计算机发送数据。为了与远程计算机进行数据传输，还可能需要连接到因特网，而 <code>socket</code> 就是用来连接到因特网的工具。</p><p><code>socket</code> 的典型应用就是 <code>Web</code> 服务器和浏览器：浏览器获取用户输入的 <code>URL</code>，向服务器发起请求，服务器分析接收到的 <code>URL</code>，将对应的网页内容返回给浏览器，浏览器再经过解析和渲染，就将文字、图片、视频等元素呈现给用户。</p><h3 id="_2-linux中的socket" tabindex="-1">2. <code>Linux</code>中的<code>socket</code> <a class="header-anchor" href="#_2-linux中的socket" aria-label="Permalink to &quot;2. `Linux`中的`socket`&quot;">​</a></h3><p>在<code>UNIX/Linux</code>系统中，为了统一对各种硬件的操作，简化接口，不同的硬件设备也都被看成一个文件。对这些文件的操作，等同于对磁盘上普通文件的操作。为了表示和区分已经打开的文件，<code>UNIX/Linux</code> 会给每个文件分配一个 <code>ID</code>，这个 <code>ID</code>就是一个整数，被称为文件描述符（<code>File Descriptor</code>），其实这个在前边学习文件<code>IO</code>的时候就了解过这个概念了。</p><p><code>UNIX/Linux</code> 程序在执行任何形式的 <code>I/O</code> 操作时，都是在读取或者写入一个文件描述符。一个文件描述符只是一个和打开的文件相关联的整数，它的背后可能是一个硬盘上的普通文件、<code>FIFO</code>、管道、终端、键盘、显示器，甚至是一个<strong>网络连接</strong>。需要注意的是网络连接也是一个文件，它也有文件描述符。</p><p><code>Linux</code>内核向应用层提供了<code>socket</code>接口，对于应用程序开发人员来说，我们只需要调用<code>socket</code>接口开发自己的应用程序即可。<code>socket</code>是应用层与<code>TCP/IP</code>协议通信的中间软件抽象层，它是一组接口。在设计模式中，<code>socket</code>其实就相当于一个门面模式，它把复杂的<code>TCP/IP</code>协议隐藏在<code>socket</code>接口后面，对我们来说，一组简单的接口就是全部，让<code>socket</code>去组织数据，以符合指定的协议。</p><p>所以，我们无需深入的去理解<code>TCP</code>、<code>UDP</code>等各种复杂的<code>TCP/IP</code>协议，前边学习过了，确实超级复杂，但是<code>socket</code>已经为我们封装好了，我们只需要遵循<code>socket</code>的规则去编程，写出的程序自然遵循<code>TCP</code>、<code>UDP</code>协议。</p><p>在<code>Linux</code>中，我们可以通过 <code>socket()</code> 函数来创建一个网络连接实现，或者说打开一个网络文件，<code>socket()</code> 的返回值就是文件描述符。有了文件描述符，我们就可以使用普通的文件操作函数来传输数据了，例如：</p><ul><li>用 <code>read()</code> 读取从远程计算机传来的数据；</li><li>用 <code>write()</code> 向远程计算机写入数据。</li></ul><h3 id="_3-windows中的socket" tabindex="-1">3. <code>Windows</code>中的<code>socket</code> <a class="header-anchor" href="#_3-windows中的socket" aria-label="Permalink to &quot;3. `Windows`中的`socket`&quot;">​</a></h3><p><code>Windows</code> 也有类似文件描述符的概念，但通常被称为文件句柄。与 <code>UNIX/Linux</code> 不同的是，<code>Windows</code> 会区分 <code>socket</code> 和文件，<code>Windows</code> 就把 <code>socket</code> 当做一个网络连接来对待，因此需要调用专门针对 <code>socket</code> 而设计的数据传输函数，针对普通文件的输入输出函数就无效了。</p><h2 id="二、套接字的类型" tabindex="-1">二、套接字的类型 <a class="header-anchor" href="#二、套接字的类型" aria-label="Permalink to &quot;二、套接字的类型&quot;">​</a></h2><p>世界上有很多种套接字（<code>socket</code>），比如 <code>DARPA Internet</code> 地址（<code>Internet</code> 套接字）、本地节点的路径名（<code>Unix</code>套接字）、<code>CCITT X.25</code>地址（<code>X.25</code> 套接字）等。我正在学习的是<code>Internet</code> 套接字，它是最具代表性的，也是最经典最常用的。</p><p>根据数据传输的方式，可以将 <code>Internet</code> 套接字分成三种类型：<strong>流式套接字</strong>、<strong>数据报套接字</strong>和<strong>原始套接字</strong>。通过 <code>socket</code> 创建连接时，我们必须要告诉它使用哪种数据传输方式才行。</p><h3 id="_1-流式套接字-sock-stream" tabindex="-1">1. 流式套接字(SOCK_STREAM) <a class="header-anchor" href="#_1-流式套接字-sock-stream" aria-label="Permalink to &quot;1. 流式套接字(SOCK_STREAM)&quot;">​</a></h3><p>流格式套接字（<code>Stream Sockets</code>）也叫“<strong>面向连接的套接字</strong>”，一般在程序中使用 <code>SOCK_STREAM</code> 表示。它提供了一个面向连接、可靠的数据传输服务，数据无差错、无重复的发送且按发送顺序接收。内设置流量控制，避免数据流淹没慢的接收方。数据被看作是字节流，无长度限制。</p><p>可以将 <code>SOCK_STREAM</code> 看成一条传送带，只要传送带本身没有问题（不断网），就能保证数据不丢失；同时，较晚传送的数据不会先到达，较早传送的数据不会晚到达，这就保证了数据是按照顺序传递的。</p><p>流式套接字可以保证数据高质量的传输，这是因为它使用了 <code>TCP</code> 协议（<code>The Transmission Control Protocol</code>，传输控制协议），前边我们已经了解过了，<code>TCP</code> 协议会控制我们的数据按照顺序到达并且没有错误。</p><p>浏览器所使用的 <code>http</code> 协议就基于面向连接的套接字，因为必须要确保数据准确无误，否则加载的 <code>HTML</code> 将无法解析。</p><h3 id="_2-数据报套接字-sock-dgram" tabindex="-1">2. 数据报套接字(SOCK_DGRAM) <a class="header-anchor" href="#_2-数据报套接字-sock-dgram" aria-label="Permalink to &quot;2. 数据报套接字(SOCK_DGRAM)&quot;">​</a></h3><p>数据报格式套接字（<code>Datagram Sockets</code>）也叫“<strong>无连接的套接字</strong>”，在程序中使用 <code>SOCK_DGRAM</code> 表示，它提供无连接服务。数据包以独立数据包的形式被发送，不提供无差错保证，数据可能丢失或重复，顺序发送，可能乱序接收，并且数据传输的时候数据包的长度是有限制的吗，一般是<code>32KB</code>。</p><p>所以使用此种套接字的话，计算机只管传输数据，不作数据校验，如果数据在传输中损坏，或者没有到达另一台计算机，是没有办法补救的。也就是说，数据错了就错了，无法重传。但是恰恰因为数据报套接字所做的校验工作少，所以在传输效率方面比流格式套接字要高。</p><p>总的来说，数据报套接字是一种不可靠的、不按顺序传递的、以追求速度为目的的套接字。它使用的是<code>UDP</code>（<code>User Datagram Protocol</code>，用户数据报协议）协议。</p><p>一般我们使用的<code>QQ</code> 视频聊天和语音聊天就使用 <code>SOCK_DGRAM</code> 来传输数据</p><h3 id="_3-原始套接字-sock-raw" tabindex="-1">3. 原始套接字(SOCK_RAW) <a class="header-anchor" href="#_3-原始套接字-sock-raw" aria-label="Permalink to &quot;3. 原始套接字(SOCK_RAW)&quot;">​</a></h3><p>原始套接字(<code>SOCK_RAW</code>)适用于实现<code>IP</code>数据包通信，可以对较低层次协议如<code>IP</code>、<code>ICMP</code>直接访问。该套接字一般不会出现在高级网络接口中，它常用于侦听及分析数据包，广泛应用于高级网络编程。使用原始套接字存在络应用程序的兼容性问题，所以一般不推荐使用原始套接字。</p><h2 id="三、工作在哪" tabindex="-1">三、工作在哪？ <a class="header-anchor" href="#三、工作在哪" aria-label="Permalink to &quot;三、工作在哪？&quot;">​</a></h2><img src="'+a+'" alt="image-20220624065401119" style="zoom:50%;"><p><code>socket</code>是用于实现<code>TCP</code>和<code>UDP</code>协议的，它就工作在传输层了，但是不能做访问网页这样的事情，因为访问网页所需要的 <code>http</code> 协议位于应用层。</p>',35)])])}const h=o(s,[["render",r]]);export{g as __pageData,h as default};
